from itertools import combinations

def is_adjacent(r1, c1, r2, c2):
    # Checks if two unit squares share a vertex (King's move adjacency)
    return abs(r1 - r2) <= 1 and abs(c1 - c2) <= 1 and (r1 != r2 or c1 != c2)

def check_constraint_1(grid_size, selected_indices):
    k = len(selected_indices)
    if k == 0:
        return True

    # Convert indices (r, c) from flat list representation to actual coordinates
    selected_coords = []
    for i in selected_indices:
        r = i // grid_size
        c = i % grid_size
        selected_coords.append((r, c))

    # Check degree for every selected square
    for i in range(k):
        r1, c1 = selected_coords[i]
        degree = 0
        for j in range(k):
            if i == j:
                continue
            r2, c2 = selected_coords[j]
            if is_adjacent(r1, c1, r2, c2):
                degree += 1

        if degree > 1:
            return False
    return True

def find_max_k(N):
    total_squares = N * N

    print(f"Searching for max k in {N}x{N} grid (Total squares: {total_squares})...")

    # Iterate k downwards
    for k in range(total_squares, 0, -1):

        # Generate all combinations of k selected squares
        found = False
        for selection in combinations(range(total_squares), k):
            if check_constraint_1(N, selection):
                print(f"Found k = {k}. Example selection: {list(selection)[:min(10, k)]}...")
                found = True
                return k

        if not found:
            print(f"k = {k} failed.")

    return 0

# Test for N=3
